type Result = { output: string; metrics?: Array<[string, string | number]>; warning?: string };
type Demo = { input: string; secondary?: string; mode?: string };

const lines = (value: string) => value.split(/\r?\n/u).map((line) => line.trim()).filter(Boolean);
const words = (value: string) => value.toLocaleLowerCase().match(/[\p{L}\p{N}]+/gu) ?? [];
const escapeHtml = (value: string) => value.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&#39;");
const pairs = (value: string) => Object.fromEntries(lines(value).map((line) => { const i = line.indexOf("="); if (i < 1) throw new Error(`Expected key=value: ${line}`); return [line.slice(0, i).trim(), line.slice(i + 1).trim()]; }));
const num = (value: string | undefined, name: string, min = -Infinity) => { const parsed = Number(value); if (!Number.isFinite(parsed) || parsed < min) throw new Error(`${name} must be a number${Number.isFinite(min) ? ` ≥ ${min}` : ""}.`); return parsed; };
const table = (rows: Array<Array<string | number>>) => rows.map((row) => `| ${row.map((cell) => String(cell).replace(/\|/g, "\\|")).join(" | ")} |`).join("\n");
const format = (value: number, digits = 2) => new Intl.NumberFormat("en-US", { maximumFractionDigits: digits }).format(value);

function parseCsv(input: string, delimiter?: string) {
  const first = input.split(/\r?\n/u)[0] ?? "";
  const selected = delimiter ?? [",", ";", "\t", "|"].sort((a, b) => first.split(b).length - first.split(a).length)[0];
  const result: string[][] = []; let row: string[] = []; let cell = ""; let quote = false;
  for (let i = 0; i < input.length; i += 1) { const ch = input[i]; if (ch === '"') { if (quote && input[i + 1] === '"') { cell += '"'; i += 1; } else quote = !quote; } else if (ch === selected && !quote) { row.push(cell); cell = ""; } else if ((ch === "\n" || ch === "\r") && !quote) { if (ch === "\r" && input[i + 1] === "\n") i += 1; row.push(cell); result.push(row); row = []; cell = ""; } else cell += ch; }
  if (quote) throw new Error("Unclosed CSV quote."); if (cell || row.length) { row.push(cell); result.push(row); } return { rows: result, delimiter: selected };
}
function csvCell(value: string) { return /[",\r\n]/.test(value) ? `"${value.replace(/"/g, '""')}"` : value; }
function byteBase32(bytes: Uint8Array) { const alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZ234567"; let bits = ""; bytes.forEach((byte) => { bits += byte.toString(2).padStart(8, "0"); }); let out = ""; for (let i = 0; i < bits.length; i += 5) out += alphabet[Number.parseInt(bits.slice(i, i + 5).padEnd(5, "0"), 2)]; return out.padEnd(Math.ceil(out.length / 8) * 8, "="); }
function base32Bytes(value: string) { const alphabet = "ABCDEFGHIJKLMNOPQRSTUVWXYZ234567"; const clean = value.toUpperCase().replace(/=+$/u, "").replace(/\s+/gu, ""); if (!clean || [...clean].some((ch) => !alphabet.includes(ch))) throw new Error("Invalid RFC 4648 Base32 input."); let bits = ""; [...clean].forEach((ch) => { bits += alphabet.indexOf(ch).toString(2).padStart(5, "0"); }); return Uint8Array.from((bits.match(/.{8}/g) ?? []).map((part) => Number.parseInt(part, 2))); }
function levenshtein(a: string, b: string) { const prev = Array.from({ length: b.length + 1 }, (_, i) => i); for (let i = 1; i <= a.length; i += 1) { let diagonal = prev[0]; prev[0] = i; for (let j = 1; j <= b.length; j += 1) { const above = prev[j]; prev[j] = Math.min(prev[j] + 1, prev[j - 1] + 1, diagonal + Number(a[i - 1] !== b[j - 1])); diagonal = above; } } return prev[b.length]; }
function safeJson(value: string) { try { return JSON.parse(value) as unknown; } catch (error) { throw new Error(`Invalid JSON: ${error instanceof Error ? error.message : String(error)}`); } }
function b64url(value: string) { const compact = value.replace(/-/g, "+").replace(/_/g, "/"); const bytes = Uint8Array.from(atob(compact.padEnd(Math.ceil(compact.length / 4) * 4, "=")), (ch) => ch.charCodeAt(0)); return new TextDecoder().decode(bytes); }

