export function FrontierWorkbench({ slug, locale }: { slug: string; locale: Locale }) {
  const t = ui[locale], demo = frontierDemos[slug] ?? { input: "" }, tool = getTool(slug);
  const options = useMemo(() => modeOptions[slug] ?? [], [slug]);
  const [input, setInput] = useState(""); const [secondary, setSecondary] = useState(""); const [mode, setMode] = useState(options[0]?.[0] ?? "default"); const [output, setOutput] = useState(""); const [metrics, setMetrics] = useState<Array<[string, string | number]>>([]); const [warning, setWarning] = useState(""); const [state, setState] = useState<"idle" | "busy" | "success" | "error">("idle"); const [message, setMessage] = useState("");
  const resetResult = () => { setOutput(""); setMetrics([]); setWarning(""); setState("idle"); setMessage(""); };
  const loadDemo = () => { setInput(demo.input); setSecondary(demo.secondary ?? ""); setMode(demo.mode ?? options[0]?.[0] ?? "default"); resetResult(); };
  async function run() { if (state === "busy") return; setState("busy"); setMessage(t.running); await new Promise<void>((resolve) => requestAnimationFrame(() => resolve())); try { if (!input.trim()) throw new Error(locale === "tr" ? "Önce bir girdi yazın veya örneği yükleyin." : "Enter input or load the example first."); if (dualSlugs.has(slug) && !secondary.trim()) throw new Error(locale === "tr" ? "Bu araç için ikinci alan da gereklidir." : "This tool also requires the second field."); const result = await runFrontierTool(slug, input.slice(0, 200_000), secondary.slice(0, 100_000), mode); setOutput(result.output); setMetrics(result.metrics ?? []); setWarning(result.warning ?? ""); setState("success"); setMessage(t.done); } catch (error) { setOutput(""); setMetrics([]); setWarning(""); setState("error"); setMessage(`${t.error}: ${error instanceof Error ? error.message : String(error)}`); } }
  async function copy() { if (!output) return; try { await navigator.clipboard.writeText(output); setMessage(t.done); } catch { setState("error"); setMessage(t.error); } }
  function download() { if (!output) return; const url = URL.createObjectURL(new Blob([output], { type: "text/plain;charset=utf-8" })); const a = document.createElement("a"); a.href = url; a.download = `bytequant-${slug}.txt`; a.click(); setTimeout(() => URL.revokeObjectURL(url), 0); }
  return <section className="workbench precision-workbench frontier-workbench" aria-busy={state === "busy"}>
    <div className="workbench-bar"><span className="local-status"><i />{t.local}<small>{tool?.title[locale]}</small></span><div className="workbench-bar-actions"><button type="button" className="demo-button" onClick={loadDemo}>{t.demo}</button><button type="button" className="ghost-button" onClick={() => { setInput(""); setSecondary(""); resetResult(); }}>{t.clear}</button></div></div>
    <div className="workbench-grid"><div className="workbench-inputs" data-agent-contract={dualSlugs.has(slug) ? "dual-text-v1" : "single-text-v1"}><label className="field-label"><span>{t.input}</span><textarea data-agent-input data-agent-key="input" value={input} rows={12} maxLength={200000} onChange={(e) => { setInput(e.target.value); resetResult(); }} spellCheck={false} /><small className="field-counter">{input.length.toLocaleString()} / 200,000</small></label>{dualSlugs.has(slug) && <label className="field-label"><span>{t.second}</span><textarea data-agent-input data-agent-key="secondary" value={secondary} rows={7} maxLength={100000} onChange={(e) => { setSecondary(e.target.value); resetResult(); }} spellCheck={false} /></label>}{options.length > 0 && <label className="field-label compact-field"><span>{t.mode}</span><select data-agent-mode value={mode} onChange={(e) => { setMode(e.target.value); resetResult(); }}>{options.map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select></label>}<button type="button" className="primary-button run-button" data-agent-run disabled={state === "busy"} onClick={() => void run()}>{state === "busy" ? t.running : t.run}<span aria-hidden="true"> →</span></button></div>
      <div className="result-panel" aria-live="polite"><div className="result-header"><span>{t.result}</span><div className="output-actions"><button type="button" disabled={!output} onClick={() => void copy()}>{t.copy}</button><button type="button" disabled={!output} onClick={download}>{t.download}</button></div></div>{metrics.length > 0 && <div className="metric-strip">{metrics.map(([label, value]) => <div key={label}><strong>{value}</strong><span>{label}</span></div>)}</div>}<StructuredToolOutput output={output} empty={t.empty} />{warning && <ToolNotice locale={locale} notice={{ kind: "warning", text: warning }} />}{state === "error" && <ToolNotice locale={locale} notice={{ kind: "error", text: message }} />}{state === "success" && <div className="workbench-trust-card"><span aria-hidden="true">✓</span><p>{t.privacy}</p></div>}</div></div>
  </section>;
}
